import {showPage,movePlanned,moveShop,reorderShop,shopEditor,saveShopEditor} from './app.e4d0fa990650.js';
const $=s=>document.querySelector(s);
const settings=document.createElement('dialog');settings.id='settings-dialog';settings.innerHTML='<h2>Impostazioni</h2><h3>Backup e trasferimento</h3><div class="sync-actions"></div><h3>Supermercati</h3><div id="settings-stores"></div><button type="button" id="close-settings">Chiudi</button>';document.body.append(settings);
for(const id of ['sync-backup','sync-upload','sync-import','sync-file'])settings.querySelector('.sync-actions').append($('#'+id));
$('#settings-stores').append($('#shopping-store-settings'));$('#shopping-store-settings').open=true;
$('#open-settings').onclick=()=>settings.showModal();$('#close-settings').onclick=()=>settings.close();
const manual=$('.manual-add');manual.querySelector('summary').innerHTML='<span id="manual-plus" role="button" aria-label="Aggiungi alla spesa">+</span>';manual.addEventListener('toggle',()=>{if(manual.open)$('#manual-name').focus()});
const editor=document.createElement('dialog');editor.id='shop-editor';editor.innerHTML='<form><h2 id="shop-editor-title">Prodotto</h2><label>Quantità<input id="shop-edit-quantity" type="number" min="0" step="any" required></label><label>Unità<input id="shop-edit-unit" maxlength="20" required></label><label>Supermercato<select id="shop-edit-store"></select></label><p role="alert" id="shop-edit-error"></p><button type="button" id="shop-edit-cancel">Annulla</button><button type="submit">Salva</button></form>';document.body.append(editor);let editing=null;
$('#shopping-list').addEventListener('click',e=>{const button=e.target.closest('[data-shop-options]');if(!button)return;editing=button.dataset.shopOptions;const {row,stores}=shopEditor(editing);$('#shop-editor-title').textContent=row.ingredient_name;$('#shop-edit-quantity').value=row.quantities.length===1&&row.quantities[0].numeric?row.quantities[0].sum:'';$('#shop-edit-unit').value=row.quantities[0]?.unit||'g';$('#shop-edit-store').replaceChildren(...stores.map(s=>new Option(s.name,s.id)));$('#shop-edit-store').value=row.storeId;editor.showModal()});
$('#shop-edit-cancel').onclick=()=>editor.close();editor.querySelector('form').onsubmit=e=>{e.preventDefault();saveShopEditor(editing,$('#shop-edit-quantity').value,$('#shop-edit-unit').value,$('#shop-edit-store').value);editor.close()};
function navigate(){const hash=location.hash.slice(1);const page=hash==='ricettario'?'recipes':hash==='calendario'?'calendar':'categories';showPage(page);$('#recipes').removeAttribute('aria-labelledby');$('#recipes').setAttribute('aria-label',page==='recipes'?'Ricettario':'Categorie');for(const [id,value] of [['nav-categories','categories'],['nav-recipes','recipes'],['nav-calendar','calendar']]){$('#'+id).toggleAttribute('aria-current',page===value);}}
window.addEventListener('hashchange',navigate);navigate();
$('#week-days').addEventListener('dragstart',e=>{if(e.target.closest('button'))return;const card=e.target.closest('[data-plan-id]');if(card)e.dataTransfer.setData('application/x-boschetto-plan',JSON.stringify({id:card.dataset.planId,day:card.dataset.planDay}));});
for(const [type,fn] of [['dragover',e=>{if(e.target.closest('[data-store-tab]'))e.preventDefault()}],['drop',e=>{const target=e.target.closest('[data-store-tab]'),id=e.dataTransfer.getData('application/x-boschetto-shopping');if(target&&id){e.preventDefault();moveShop(id,target.dataset.storeTab)}}]])$('#shopping-store-tabs').addEventListener(type,fn);
// A dedicated grip permits normal touch scrolling everywhere else in the row.
function grips(){for(const row of document.querySelectorAll('[data-shop-key],[data-plan-id]'))if(!row.querySelector('.shop-grip')){const grip=document.createElement('button');grip.type='button';grip.className='shop-grip';grip.textContent='⠿';grip.setAttribute('aria-label','Trascina '+(row.querySelector('.shop-name,strong')?.textContent||'ricetta'));row.append(grip);}}
new MutationObserver(grips).observe($('#shopping-list'),{childList:true,subtree:true});new MutationObserver(grips).observe($('#week-days'),{childList:true,subtree:true});grips();
let drag=null,frame=null;
function tick(){if(!drag)return;const panel=drag.shop?$('#shopping-drawer'):document.scrollingElement;const box=drag.shop?panel.getBoundingClientRect():{top:0,bottom:innerHeight};const speed=drag.y<box.top+70?-14:drag.y>box.bottom-70?14:0;if(speed)panel.scrollTop+=speed;frame=requestAnimationFrame(tick)}
document.addEventListener('pointerdown',e=>{const grip=e.target.closest('.shop-grip');if(!grip)return;const row=grip.closest('[data-shop-key],[data-plan-id]');drag={row,shop:!!row.dataset.shopKey,x:e.clientX,y:e.clientY,pointer:e.pointerId};grip.setPointerCapture(e.pointerId);row.classList.add('touch-dragging');e.preventDefault();tick()});
document.addEventListener('pointermove',e=>{if(!drag)return;drag.x=e.clientX;drag.y=e.clientY;e.preventDefault()},{passive:false});
function finish(e){if(!drag)return;const current=drag;drag=null;cancelAnimationFrame(frame);current.row.classList.remove('touch-dragging');if(e.type==='pointercancel')return;const target=document.elementFromPoint(e.clientX,e.clientY);if(current.shop){const store=target?.closest('[data-store-tab]');if(store)moveShop(current.row.dataset.shopKey,store.dataset.storeTab);else{const row=target?.closest('[data-shop-key]');if(row&&row!==current.row){reorderShop(current.row.dataset.shopKey,row.dataset.shopKey);}}}else{const day=target?.closest('[data-day]');if(day)movePlanned(current.row.dataset.planDay,current.row.dataset.planId,day.dataset.day)}}
document.addEventListener('pointerup',finish);document.addEventListener('pointercancel',finish);
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(console.error);
